// ⫘⫘⫘ ล้าง alias / ทำ norm ⫘⫘⫘
function cleanAlias(raw) {
  if (!raw) return "";
  return raw
    .toString()
    .replace(/\|+/g, " ")              // ล้าง |||||||||
    .replace(/_{2,}/g, " ")            // ล้าง ________
    .replace(/`+/g, "")                // ล้าง ` ` `
    .replace(/<code>|<\/code>/gi, "")
    .replace(/^[^\wก-๙]+/g, "")        // ตัด emoji หน้า "🍉CAVALLO"
    .replace(/\s{2,}/g, " ")
    .trim();
}

function toNorm(raw) {
  if (!raw) return "";
  // ทำตัวเล็ก + ล้างซ้ำอีกชั้น = alias_norm ไว้ค้นหา
  return cleanAlias(raw).toLowerCase().trim();
}
let ALL_PRODUCT_KEYWORDS=[];
for(let skuKey in PRODUCT_MASTER){ for(let kw of PRODUCT_MASTER[skuKey].keywords){ ALL_PRODUCT_KEYWORDS.push({skuKey, keyword:String(kw).toUpperCase().trim()}); } }
ALL_PRODUCT_KEYWORDS.sort((a,b)=>b.keyword.length-a.keyword.length);

function extractMessages(obj, pageIdFromParent = "") {
  let messages = [];
  if (Array.isArray(obj)) {
    obj.forEach(item => { messages = messages.concat(extractMessages(item, pageIdFromParent)); });
  } else if (typeof obj === 'object' && obj !== null) {
    if (obj.message && obj.id) { 
      let cleanedMsg = obj.message.replace(/udfe[0-9a-fA-F]{0,4}/gi, "").replace(/\\?ud[0-9a-fA-F]+/gi, "");
      messages.push({ ...obj, message: cleanedMsg, page_id_inherited: pageIdFromParent }); 
    }
    let currentPageId = pageIdFromParent;
    if (obj.participants?.data) {
      const pageP = obj.participants.data.find(p => p.id?.length > 10);
      if (pageP) currentPageId = pageP.id;
    }
    for (const key in obj) { messages = messages.concat(extractMessages(obj[key], currentPageId)); }
  }
  return messages;
}

for (const item of items) {
  const convs = item.json.data || [];
  for (const conv of convs) {
    const allMessages = extractMessages(conv);
    for (const m of allMessages) {
      if (!m.message || seen.has(m.id)) continue;
      seen.add(m.id);

      const currentPageId = m.from?.id || m.page_id_inherited || m.page_id || "";
      const masterConfigNode = MASTERCONFIG.find(p => p.page_id === currentPageId);
      if (!masterConfigNode || masterConfigNode.system_status !== "ON") continue;

      const realPageName = masterConfigNode.page_name;
      const page_id = masterConfigNode.page_id;
      const assignedAgent = masterConfigNode.assigned_agent;  
      const admin_name = masterConfigNode.admin_name;    

      let SNIPER_X_TEXT = m.message || "";        
      SNIPER_X_TEXT = SNIPER_X_TEXT.replace(/\\n/g, '\n').replace(/\\\s*n/gi, '\n');

      if (!/cod/i.test(SNIPER_X_TEXT)) continue;

      let fbCustomerName = ""; 
      let realTargetId = ""; 
      let threadId = conv?.id || ""; 
      if (conv?.participants?.data) {
        const custPart = conv.participants.data.find(p => p.id !== page_id);
        if (custPart) { fbCustomerName = custPart.name || ""; realTargetId = custPart.id || ""; }
      }

      const codMatch = SNIPER_X_TEXT.match(/(?:COD|ยอดรวมCOD|ยอดเงิน|ยอด)\s*[:：]?\s*(?:\s*\[\s*([0-9,]+)\s*\]|\s*([0-9,]+))/i);
      const rawCodValue = codMatch ? (codMatch[1] || codMatch[2]) : "0";
      const hascodAmount = parseInt(rawCodValue.replace(/,/g, '')) || 0;
      if (hascodAmount < 200) continue;

      let customer_name = "ไม่ระบุชื่อ";
      const nameMatch = SNIPER_X_TEXT.match(/(?:👤\s*ชื่อ|ชื่อ)\s*[:：]?\s*([ก-๙a-zA-Z\.\s]+?)(?=\s*📱|\s*📍|\s*📮|$)/i);
      if (nameMatch && nameMatch[1]) {
          customer_name = nameMatch[1].replace(/^(?:คุณ|นาย|นาง|นางสาว|น\.ส\.|K\.)\s*/i, "").trim();
      } else {
          const lines = SNIPER_X_TEXT.split("\n").map(l => l.trim()).filter(Boolean);
          for (let l of lines) {
              if (/^(?:คุณ|นาย|นาง|นางสาว|น\.ส\.|K\.)/.test(l)) {
                  customer_name = l.replace(/^(?:คุณ|นาย|นาง|นางสาว|น\.ส\.|K\.)\s*/i, "").replace(/[📱📍📮].*$/, "").trim();
                  break;
              }
          }
      }
      if ((!customer_name || customer_name === "ไม่ระบุชื่อ") && fbCustomerName) {
          customer_name = fbCustomerName.replace(/^(?:คุณ|นาย|นาง|นางสาว|น\.ส\.|K\.)\s*/i, "").trim();
      }

      // 🎯 1. สกัดเบอร์โทรศัพท์ 10 หลัก (Zero-Inference Phone Engine)
      let validatedPhone = "";
      const phoneMatch = SNIPER_X_TEXT.match(/0[689][0-9\s-]{8,13}\d/);
      if (phoneMatch) {
        let cleanP = phoneMatch[0].replace(/[^0-9]/g, "");
        if (cleanP.length === 10) validatedPhone = cleanP;
      } 
      if (!validatedPhone) {
        const generalPhoneMatch = SNIPER_X_TEXT.match(/(?:📱|เบอร์)?\s*[:：]?\s*(0[0-9\s-]{8,15})/);
        if (generalPhoneMatch) {
            let cleanP = generalPhoneMatch[1].replace(/[^0-9]/g, "");
            if (cleanP.length === 10 && cleanP.startsWith("0")) validatedPhone = cleanP;
        }
      }
      if (!validatedPhone) continue;

      // 🎯 2. สกัดรหัสไปรษณีย์
      let hasshipping_zipcode = "";
      const zipMatch = SNIPER_X_TEXT.match(/(?:รหัสไปรษณีย์|ไปรษณีย์|ZIP)?\s*[:：]?\s*\b([1-9][0-9]{4})\b/i);
      if (zipMatch) {
          hasshipping_zipcode = zipMatch[1];
      } else {
          const allZips = SNIPER_X_TEXT.match(/\b([1-9][0-9]{4})\b/g);
          if (allZips) {
              for (let z of allZips) { if (!validatedPhone.includes(z)) { hasshipping_zipcode = z; break; } }
          }
      }

      let finalAddressClean = "";
      const addrMatch = SNIPER_X_TEXT.match(/(?:📍\s*ที่อยู่|ที่อยู่)\s*[:：]?\s*([^\r\n]+)/i);
      if (addrMatch && addrMatch[1]) {
          finalAddressClean = addrMatch[1].replace(/┌[─]*┐|└[─]*┘/g, "").replace(/📮.*$/, "").trim();
      } else {
          const lines = SNIPER_X_TEXT.split("\n").map(l => l.trim()).filter(Boolean);
          for (let l of lines) {
              if (/\d+[\/\d]*\s+(?:ซอย|ถนน|ม\.|หมู่|ต\.|อ\.|จ\.|แขวง|เขต)/i.test(l)) {
                  finalAddressClean = l.replace(/┌[─]*┐|└[─]*┘/g, "").trim();
                  break;
              }
          }
      }
      if (!finalAddressClean) finalAddressClean = SNIPER_X_TEXT;

      // =================================================================
      // ✂️ SURGICAL ADDRESS CLEANER V.70 (RESCUE FIXED - ZERO-ERROR)
      // =================================================================
      let rawAddressBody = finalAddressClean
        .replace(/```/g, "").replace(/`+/g, "")
        .replace(/[━─═\-_~]{2,}/g, "")
   .replace(/🤖.*?(สรุป|รายการ).*?💰/gi,"")
   .replace(/\[สรุปรายการ.*?\]/gi,"")
   .replace(/⏰.*?(น\.|น\b)/gi,"")
   .replace(/💰.*?(บาท|฿)?/gi,"")
   .replace(/```/g,"")
   .replace(/\s{2,}/g," ")
        .replace(/\b(COD|ยอดรวม|สรุปรายการ|รายการสินค้า).*$/gms, "")
        .replace(/\b0[0-9]{8,9}\b/g, "")
        .replace(/เลขไปรษณีย์|รหัสไปรษณีย์|ไปรษณีย์/g, "")
        .trim();

      if (customer_name && customer_name.length > 2) {
        rawAddressBody = rawAddressBody.replace(new RegExp(customer_name, "gi"), "").trim();
      }

      // 🎯 3. สกัด ตำบล/แขวง , อำเภอ/เขต , จังหวัด (Surgical Precision)
      let hassubDistrict = "";
      const subDistMatch = rawAddressBody.match(/(?:แขวง|ต\s*\.\s*|ตำบล)\s*([ก-๙a-zA-Z]+)/);
      if (subDistMatch) {
          hassubDistrict = subDistMatch[1];
      } else {
          // Fallback: สแกนหาคำว่า ต. หรือ ตำบล
