    let matchedBrand = null;
    let matchedColor = null;

    for (let [bKey, keywords] of Object.entries(SMART_BRANDS)) {
        if (keywords.some(kw => lineUpper.includes(kw))) {
            matchedBrand = bKey;
            break;
        }
    }

    for (let [cKey, keywords] of Object.entries(SMART_COLORS)) {
        if (keywords.some(kw => lineUpper.includes(kw))) {
            matchedColor = cKey;
            break;
        }
    }

    if (matchedBrand && matchedColor) {
        let rawKey = `${matchedBrand}_${matchedColor}`;
        return SMART_SKU_MAPPER[rawKey] || rawKey;
    }
    return null;
}

