            let tLine = line.trim();
            if (tLine.length < 3 || tLine.toLowerCase().includes('cod') || tLine.match(/^[0-9]{10}$/)) continue;
            let isAddress = tLine.includes("วัด") || tLine.includes("ตึก") || tLine.includes("อาคาร") || tLine.includes("หมู่บ้าน") || tLine.includes("บ้าน") ||
                tLine.includes("โรงเรียน") || tLine.includes("โรงแรม") || tLine.includes("สถานี") || tLine.includes("ตลาด") ||
                (/\d+[\/]?\d*/.test(tLine) && (tLine.includes("ถนน") || tLine.includes("ซอย") || tLine.includes("หมู่") || tLine.includes("ตำบล") || tLine.includes("อำเภอ") || tLine.includes("จังหวัด") || tLine.includes("ต.") || tLine.includes("อ.") || tLine.includes("จ.") || tLine.includes("แขวง") || tLine.includes("เขต") || tLine.includes("ค่าย") || tLine.includes("กทม")));

            if (isAddress && !collectedLines.includes(tLine)) collectedLines.push(tLine);
        }
        rawAddressOnly = collectedLines.join(" ");
    }

    // --- SMART EXTRACTION FOR EMBEDDED NAME/PHONE IN ADDRESS ---
    let isolatedName = "";
    let directNameMatch = rawText.match(/(?:ชื่อ:|👤ชื่อ:)\s*([^\n📱📍📮]+)/i);
    if (directNameMatch && directNameMatch[1]) {
        isolatedName = directNameMatch[1].replace(/[✅❎⭐🥰|]/g, '').trim();
    }

    // Handle embedded name & leading numbers inside rawAddressOnly (e.g. "200เสกสรร ชาญสำโรง บ้านเลขที่...")
    if (rawAddressOnly) {
        // Strip leading phone if attached
        let leadPhoneMatch = rawAddressOnly.match(/^(\d{9,10})\s+(.*)/);
        if (leadPhoneMatch) {
            if (isolatedPhone === "DATA_MISSING") isolatedPhone = leadPhoneMatch[1];
            rawAddressOnly = leadPhoneMatch[2];
        }

        // Strip leading number + name (e.g. "200เสกสรร ชาญสำโรง 111/6...")
        let leadNumNameMatch = rawAddressOnly.match(/^(\d+)?\s*([\u0e00-\u0e7fa-zA-Z\.\s]{2,35})\s+(?:บ้านเลขที่|เลขที่|\d+\/|ม\.|ซอย|ถนน|ชุมชน)/i);
        if (leadNumNameMatch) {
            if (!isolatedCod && leadNumNameMatch[1] && parseInt(leadNumNameMatch[1]) > 99) {
                isolatedCod = parseInt(leadNumNameMatch[1], 10);
            }
            if (!isolatedName || isolatedName === "ไม่ระบุชื่อ") {
                isolatedName = leadNumNameMatch[2].trim();
            }
            rawAddressOnly = rawAddressOnly.replace(leadNumNameMatch[0], '').trim();
        }
    }

    if (!isolatedName || isolatedName.length <= 1 || isolatedName.length > 35 || isolatedName.includes("ขอบคุณ") || isolatedName.includes("แอดไลน์")) {
        isolatedName = String(j.customer_name || j.facebook_name || "ไม่ระบุชื่อ").trim();
    }

    let parsedDistrict = "";
    let parsedAmphoe = "";
    let parsedProvince = "";

    let distMatch = rawText.match(/(?:ตำบล|ต\.|แขวง)\s*([^\s,]+?)(?=\s*(?:อำเภอ|อ\.|เขต|จังหวัด|จ\.|[0-9]|$))/i);
    let amphMatch = rawText.match(/(?:อำเภอ|อ\.|เขต)\s*([^\s,]+?)(?=\s*(?:จังหวัด|จ\.|[0-9]|$))/i);
    let provMatch = rawText.match(/(?:จังหวัด|จ\.)\s*([^\s,0-9]+)/i);

    if (distMatch) parsedDistrict = distMatch[1].replace(/^(ตำบล|ต\.|แขวง)/, '').trim();
    if (amphMatch) parsedAmphoe = amphMatch[1].replace(/^(อำเภอ|อ\.|เขต)/, '').trim();
    if (provMatch) parsedProvince = provMatch[1].replace(/^(จังหวัด|จ\.)/, '').trim();

    if (!parsedProvince || !parsedAmphoe) {
        let cleanForTokens = rawText.replace(isolatedZipcode, '').replace(/[^\u0e00-\u0e7fa-zA-Z0-9\s]/g, ' ').trim();
        let tokens = cleanForTokens.split(/\s+/).filter(t => t.length > 0);
        if (tokens.length >= 3) {
            if (!parsedProvince) parsedProvince = tokens[tokens.length - 1];
            if (!parsedAmphoe) parsedAmphoe = tokens[tokens.length - 2];
            if (!parsedDistrict) parsedDistrict = tokens[tokens.length - 3];
        }
    }

    if ((!parsedProvince || !parsedAmphoe) && isolatedZipcode !== "DATA_MISS" && zipcodeDb[isolatedZipcode]) {
        let matchLoc = zipcodeDb[isolatedZipcode][0];
        if (!parsedDistrict) parsedDistrict = matchLoc.district;
        if (!parsedAmphoe) parsedAmphoe = matchLoc.amphoe;
        if (!parsedProvince) parsedProvince = matchLoc.province;
    }

    let cleanAddressBase = rawAddressOnly
        .replace(/.*?(?:เลขที่ออเดอร์|เวลาสั่งซื้อ|เบอร์โทรศัพท์|เบอร์|📍\s*ที่อยู่|ที่อยู่จัดส่ง|ที่อยู่)\s*[:.-]\s*/gi, '')
        .replace(/(?:COD|ยอดเงิน|ยอดรวมCOD|คอด)\s*[:\s]*\d+/gi, '')
        .replace(new RegExp(`\\b${isolatedZipcode}\\b`, 'g'), '')
        .replace(/[\ud83c-\udbff][\udc00-\udfff]|[\u{1F000}-\u{1F9FF}]/gu, ' ')
        .replace(/[■□ ━〰🔸▫️🔺▼🔺▼.◦⊱✿✧･ﾟ🚚*▭▬🔺▼]+$/g, '')
        .replace(/\s+/g, ' ')
        .trim();

    let parsedAddressShort = cleanAddressBase.replace(/(?:ตำบล|ต\.|แขวง|อำเภอ|อ\.|เขต|จังหวัด|จ\.).*/ui, '').replace(/^[📍:\s\-\–\—\•\·]+/g, '').trim();
    if (!parsedAddressShort) parsedAddressShort = cleanAddressBase;

    let parsedLocationOnly = `${parsedAddressShort} ${parsedDistrict} ${parsedAmphoe} ${parsedProvince} ${isolatedZipcode}`.trim();
    if (!parsedProvince && (rawText.includes("กทม") || rawText.includes("กรุงเทพ"))) parsedProvince = "กรุงเทพมหานคร";

    let skuMap = {};

    for (let lineStr of lines) {
        let upperStr = lineStr.toUpperCase();
        let cleanLineStr = upperStr.replace(/[\(\)\[\]\{\}]/g, ' '); 
        let matchedKey = null;

        if (upperStr.includes("เจ้าค่ะ") || upperStr.includes("นายท่าน") || upperStr.includes("มิล่า") || upperStr.includes("HTTPS://")) continue;

        for (let skuKey in PRODUCT_MASTER) {
            let keywords = PRODUCT_MASTER[skuKey].keywords;
            if (keywords.some(kw => upperStr.includes(String(kw).toUpperCase().trim()) || cleanLineStr.includes(String(kw).toUpperCase().trim()))) {
                matchedKey = skuKey;
                break;
            }
        }

        if (!matchedKey) {
            let smartCandidate = trySmartMatching(cleanLineStr);
            if (smartCandidate && PRODUCT_MASTER[smartCandidate]) matchedKey = smartCandidate;
        }

        let lineQty = 1;
        let qtyMatch = lineStr.match(/(?:จำนวน|\*|x|X)\s*(\d+)/i) || 
                       lineStr.match(/(\d+)\s*(?:คอต|กล่อง|ซอง|คอตตอน|ชุด)/i) || 
                       lineStr.match(/\s+(\d+)\s*$/);
        if (qtyMatch) {
            let parsed = parseInt(qtyMatch[1], 10);
            if (parsed > 0 && parsed < 100) lineQty = parsed;
        }

        if (matchedKey) {
            skuMap[matchedKey] = (skuMap[matchedKey] || 0) + lineQty;
        }
    }

    let parsedKeys = Object.keys(skuMap);
    let isUnmatched = (parsedKeys.length === 0);
    let auditStatus = isUnmatched ? "NEEDS_REMAP" : "READY";
    let auditFlags = [];

    if (isUnmatched) auditFlags.push("❌ สินค้าไม่ตรง SKU (ต้องรีแมฟ)");
    if (isolatedCod <= 0) auditFlags.push("⚠️ ยอด COD เป็น 0 หรือไม่พบข้อมูล");
    if (isolatedZipcode === "DATA_MISS") auditFlags.push("⚠️ ไม่พบรหัสไปรษณีย์");

    let badgeText = auditStatus === "READY" ? "🟢 พร้อมแพ็ก" : "🔴 รอตรวจสอบ/รีแมฟ";

    if (isUnmatched) {
        result.push({
            json: {
                ...j,
                singto_empires_pkey: j.singto_empires_pkey,
                parser_mode: "singto_freeform_clean",
                cod_amount: isolatedCod,
                customer_name: isolatedName,
                phone: isolatedPhone,
                addressclean: parsedAddressShort,
                parsedLocationOnly: parsedLocationOnly,
                district: parsedDistrict,
                amphoe: parsedAmphoe,
                province: parsedProvince,
                zipcode: isolatedZipcode,
                parsed_quantity: 1,
                sku: "UNMATCHED",
                product_name: "ไม่สามารถระบุสินค้า",
                th_name: "ไม่สามารถระบุสินค้า",
                parsed_product_raw: "ไม่สามารถระบุสินค้า | จำนวน 1 คอต",
                display_for_packer: "📦 ไม่สามารถระบุสินค้า | จำนวน 1 คอต",
                audit_status: auditStatus,
                audit_flags: auditFlags.join(" | "),
                audit_badge: badgeText,
                is_ready_to_pack: false,
                updated_at: new Date().toISOString()
            }
        });
    } else {
        let combinedSkuList = [];
        let combinedDisplayList = [];
        let primarySku = parsedKeys[0];
        let primaryProj = PRODUCT_MASTER[primarySku] || { name: primarySku, thName: primarySku, emo: "📦" };
        let totalQuantity = 0;

        for (let skuKey of parsedKeys) {
            let qty = skuMap[skuKey];
            let proj = PRODUCT_MASTER[skuKey] || { name: skuKey, thName: skuKey, emo: "📦" };
            totalQuantity += qty;
            combinedSkuList.push(skuKey);
            combinedDisplayList.push(`${proj.emo || "📦"} ${proj.name}(${proj.thName}) ${qty} คอต`);
        }

        result.push({
            json: {
                ...j,
                singto_empires_pkey: j.singto_empires_pkey,
                parser_mode: "singto_explicit_template",
                cod_amount: isolatedCod,
                customer_name: isolatedName,
                phone: isolatedPhone,
                addressclean: parsedAddressShort,
                parsedLocationOnly: parsedLocationOnly,
                district: parsedDistrict,
                amphoe: parsedAmphoe,
                province: parsedProvince,
                zipcode: isolatedZipcode,
                sku: primarySku,
                product_name: primaryProj.name,
                th_name: primaryProj.thName,
                parsed_quantity: totalQuantity,
                parsed_product_raw: combinedSkuList.join(", "),
                display_for_packer: combinedDisplayList.join(" + "),
                aliases: combinedSkuList.join(", "),
                audit_status: auditStatus,
                audit_flags: auditFlags.length > 0 ? auditFlags.join(" | ") : "✅ ข้อมูลสมบูรณ์",
                audit_badge: badgeText,
                is_ready_to_pack: true,
                updated_at: new Date().toISOString()
            }
        });
    }
}

return result;

// ======================================================= //
// 📥 THE GATEKEEPER: AUTO + ปั๊มขาวกันตาย + ปั๊มอีโมจิ (ฉบับเสถียร 100%) //
// ======================================================= //
const items = $input.all();
const result = [];

// 📅 1. ตั้งต้นฐานเวลาเครื่องไทยปัจจุบันที่แม่นยำที่สุด ป้องกันเอ๋อช่วงเที่ยงคืน
const now = new Date();
const bkkString = now.toLocaleString("en-US", {timeZone: "Asia/Bangkok"});
const nowBKK = new Date(bkkString);

const todayD = nowBKK.getDate();
const todayM = nowBKK.getMonth();
const todayY = nowBKK.getFullYear();

const dayNames = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
const autoDayName = dayNames[nowBKK.getDay()];

const colorMap = {
  "Sunday":    { color: "🔴 Red", emoji: "🌹" },
  "Monday":    { color: "🟡 Yellow", emoji: "🌻" },
  "Tuesday":   { color: "🌸 Pink", emoji: "🎀" },
  "Wednesday": { color: "🟢 Green", emoji: "🌿" },
  "Thursday":  { color: "🟠 Orange", emoji: "🍊" },
  "Friday":    { color: "🔵 Blue", emoji: "💎" },
  "Saturday":  { color: "🟣 Purple", emoji: "🍇" }
};

// 🧬 2. ฟังก์ชันตรวจสอบปฏิทินจริงร้อยปี แกะฟอร์แมต ค.ศ./พ.ศ. ได้หมดจด
function parseOrderDate(raw) {
  if (!raw) return null;
  raw = String(raw).trim();
  try {
    // รองรับฟอร์แมตเครื่องหมายสแลช / (เช่น 21/7/2569)
    if (raw.includes('/')) {
      const datePart = raw.split(' ')[0];
      const [d, m, y] = datePart.split('/');
      const baseY = Number(y) > 2500 ? Number(y) - 543 : Number(y);
      return new Date(baseY, Number(m) - 1, Number(d));
    }
    // รองรับฟอร์แมตเครื่องหมายขีด - (เช่น 2026-07-21)
    if (raw.includes('-')) {
      const datePart = raw.split(' ')[0];
      const [y, m, d] = datePart.split('-');
      const baseY = Number(y) > 2500 ? Number(y) - 543 : Number(y);
      return new Date(baseY, Number(m) - 1, Number(d));
    }
    return new Date(raw);
  } catch {
    return null;
  }
}

const todaySetting = colorMap[autoDayName];

// 🔄 3. วนลูปประมวลผลจบในรอบเดียว ข้อมูลไม่ตกหล่น
for (const item of items) {
  const d = item.json || item;
  const rawTime = d.order_time || d.ordered_at || d.updated_at || "";
  const orderDate = parseOrderDate(rawTime);

  let isToday = false;
  let orderDayName = autoDayName;

  if (orderDate) {
    isToday = orderDate.getDate() === todayD && orderDate.getMonth() === todayM && orderDate.getFullYear() === todayY;
    // 🎯 ล็อกคอชื่อวันตามตัวเลขปฏิทินจริงในบิล (แก้บั๊กชื่อวันจากหน้าบ้านพ่น Tuesday ช่วงเที่ยงคืน)
    orderDayName = dayNames[orderDate.getDay()];
  } else {
    isToday = true;
  }

  const settingByOrderDay = colorMap[orderDayName] || { color: "⚪ White", emoji: "⚪" };
  const settingToday = todaySetting;

  // 🛡️ ระบบการจัดการสีจัดสรรลงท่อ
  if (isToday) {
    d.status_color = settingToday.color;
    d.routing_tag = settingToday.color;
    d.status_color_backup = "⚪ White";
    d.routing_tag_backup = "⚪ White";
    d.is_safety_white = true;
  } else {
    d.status_color = settingByOrderDay.color;
    d.routing_tag = settingByOrderDay.color;
    d.status_color_backup = "👻 Ghost_Black";
    d.routing_tag_backup = "👻 Ghost_Black";
    d.is_safety_white = false;
  }

  // พ่นค่าชื่อวันตามจริงส่งต่อไปตารางและตัวสวิตช์เราเตอร์
  d.day_of_week = orderDayName;
  d.order_day = orderDayName; 

  // 🎀 4. ปั๊มอีโมจิหน้า order_number ป้องกันบวม
  if (d.order_number && !String(d.order_number).includes(settingByOrderDay.emoji)) {
    let cleanOrderNo = String(d.order_number).replace(/^[^\w]+_/, '');
    if (cleanOrderNo.startsWith("ORD-")) {
      d.order_number = `${settingByOrderDay.emoji}_${cleanOrderNo}`;
    } else {
      d.order_number = `${settingByOrderDay.emoji}_${d.order_number}`;
    }
  }

  if (d.hasOwnProperty('routing_flag')) delete d.routing_flag;

//⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘
// 🎯 5. ระบบปั๊มแฮชแท็กกันซ้ำออเดอร์ซ้อน (เวอร์ชันปลอดภัย 100%)
//⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘⫘

const tsParts = bkkString.split(', ')[1].split(' ')[0].split(':'); // เจาะเวลาจาก bkkString
let randomSuffix = Math.floor(Math.random() * 90000) + 10000;    // สุ่มเลข 5 หลักกันชนกันในเสี้ยววิ

// ประกอบร่างแฮชแท็ก: วัน + เดือน + ชั่วโมง + นาที + วินาที + เลขสุ่ม
const t8 = String(todayD).padStart(2,'0') + 
           String(todayM).padStart(2,'0') + 
           tsParts[0].padStart(2,'0') + 
           tsParts[1].padStart(2,'0') + 
           tsParts[2].padStart(2,'0') + "_" + randomSuffix;

d.Assigned_Hashtag = `⭐#SINGTO_ORDER_${t8}`;

  result.push({ json: d });
}

return result;

