function value(row, key) {
  const v = row?.[key];
  return v === undefined || v === null ? '' : String(v).trim();
}
function firstExisting(row, keys) {
  for (const key of keys) { const v = value(row, key); if (v !== '') return v; }
  return '';
}
function norm(text) {
  return String(text ?? '').toLowerCase().normalize('NFC')
    .replace(/\s+/g, '').replace(/[|()\[\]{}:：,，._-]/g, '');
}
function numberOrNull(raw) {
  if (raw === null || raw === undefined || String(raw).trim() === '') return null;
  const n = Number(String(raw).replaceAll(',', '').replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : null;
}
function rawBlock(row) {
  return firstExisting(row, ['sniper_x_text_clean', 'clean_text', 'single_cleaned_block', 'raw_message', 'message_text', 'order_text', 'original_message']);
}
function parseQty(chunk) {
  let raw = String(chunk ?? '').trim();
  let qty = null;
  const end = raw.match(/(\d+(?:\.\d+)?)\s*(?:คอต|คอตตอน|carton|กล่อง|ชิ้น)?\s*$/iu);
  if (end) { qty = Number(end[1]); raw = raw.slice(0, end.index).trim(); }
  else {
    const start = raw.match(/^\s*(\d+(?:\.\d+)?)\s*(?:คอต|คอตตอน|carton|กล่อง|ชิ้น)?\s+/iu);
    if (start) { qty = Number(start[1]); raw = raw.slice(start[0].length).trim(); }
  }
  return { raw, qty: Number.isFinite(qty) && qty > 0 ? qty : null };
}
