}
const PRODUCTS = productRows();
function resolve(rawName) {
  const n = norm(rawName);
  // Hard-stop generic product names: never choose the first SKU in Master.
  const GENERIC_AMBIGUOUS = new Set(['แตงโม', 'มะม่วง', 'เขียว', 'แดง']);
  if (GENERIC_AMBIGUOUS.has(n)) return { product: null, reason: 'AMBIGUOUS_ALIAS' };
  const direct = PRODUCTS.find((p) => norm(p.sku) === n);
  if (direct) return { product: direct, reason: 'EXACT_SKU' };
  const extraSku = Object.entries(EXTRA_ALIASES).find(([alias]) => norm(alias) === n)?.[1];
  if (extraSku) return { product: PRODUCTS.find((p) => p.sku === extraSku) || null, reason: 'ALIAS_EXACT' };
  const matches = [];
  for (const p of PRODUCTS) for (const kw of p.keywords) if (norm(kw) === n) matches.push(p);
  const unique = [...new Map(matches.map((p) => [p.sku, p])).values()];
  if (unique.length === 1) return { product: unique[0], reason: 'ALIAS_EXACT' };
  if (unique.length > 1) return { product: null, reason: 'AMBIGUOUS_ALIAS' };
  return { product: null, reason: 'UNRESOLVED' };
}
function display(p) { return `${p.emoji} \${p.sku}(\${p.th_name})`; }
