    const p = resolved.product;
    const qty = parsed.qty ?? numberOrNull(firstExisting(row, ['extracted_qty', 'quantity', 'qty'])) ?? 1;
    const itemExpected = p.unit_price === null ? null : p.unit_price * qty;
