  return m ? numberOrNull(m[1]) : null;
}
function formatBaht(n) { return n === null ? '' : new Intl.NumberFormat('th-TH').format(n); }
function escapeHtml(v) { return String(v ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;'); }

