];

function parseOrderDate(raw) {
    if (!raw) return null;
    raw = String(raw).trim();
    try {
        // รองรับรูปแบบ DD/MM/YYYY หรือ DD/MM/YY ทั้งแบบมีเวลาและไม่มีเวลา
        if (raw.includes('/')) {
            const datePart = raw.split(' ')[0];
            const timePart = raw.split(' ')[1] || "00:00:00";
            const [d, m, y] = datePart.split('/');
            const baseY = Number(y) > 2500 ? Number(y) - 543 : Number(y);

            const [hh, mm, ss] = timePart.split(':').map(Number);
            return new Date(baseY, Number(m) - 1, Number(d), hh || 0, mm || 0, ss || 0);
        }
        if (raw.includes('-')) {
            const datePart = raw.split(' ')[0];
            const timePart = raw.split(' ')[1] || "00:00:00";
            const [y, m, d] = datePart.split('-');
            const baseY = Number(y) > 2500 ? Number(y) - 543 : Number(y);

            const [hh, mm, ss] = timePart.split(':').map(Number);
            return new Date(baseY, Number(m) - 1, Number(d), hh || 0, mm || 0, ss || 0);
        }
        return new Date(raw);
    } catch {
        return null;
    }
}

const preFilteredItems = [];

