    j.message_ref_id = j.id;

    const orderTimeRaw = j.order_time || j.ordered_at || "";
    let orderDateStr = "";
    let orderDateObj = parseOrderDate(orderTimeRaw);

    if (orderTimeRaw) {
        const rawDatePart = String(orderTimeRaw).split(' ')[0];
        const dateParts = rawDatePart.split('/');
        if (dateParts.length === 3) {
            const d = String(dateParts[0].trim()).padStart(2, '0');
            const m = String(dateParts[1].trim()).padStart(2, '0');
            const y = dateParts[2].trim();
            orderDateStr = `${d}/${m}/${y}`;
        }
    }

    if (!orderNum || orderNum.length < 5) {
        continue; 
    }

    if (sniperText.includes("👻") || sniperText.includes("Ghost_Black") || sniperText.toLowerCase().includes("black")) {
        continue;
    }

    let isToday = false;
    let orderDayName = autoDayName;
    if (orderDateObj && !isNaN(orderDateObj.getTime())) {
        isToday = orderDateObj.getDate() === todayD && orderDateObj.getMonth() === todayM && orderDateObj.getFullYear() === todayY;
        orderDayName = dayNames[orderDateObj.getDay()];

        // 🛑 กฎเหล็กใหม่: ถ้ามี timestamp ให้เช็คว่าเก่ากว่า "บ่าย 2 โมงเมื่อวาน" หรือไม่ ถ้าเก่ากว่าให้ดีดทิ้งทันที
        if (orderDateObj.getTime() < yesterdayBKK.getTime()) {
            continue; // ดีดทิ้งเพราะสั่งก่อน 14:00 ของเมื่อวาน
        }
    } else if (orderDateStr) {
        isToday = todayMatches.includes(orderDateStr);
        if (!isToday) {
            // ถ้าเป็นวันที่อื่นที่ไม่ใช่วันนี้และไม่มีเวลาชัดเจน ให้ดีดทิ้งเพื่อความปลอดภัย
            continue;
        }
    } else {
        isToday = true;
    }

    j.is_today_order = isToday;
    j.order_day_name = orderDayName;
    preFilteredItems.push({ json: j });
}

for (const item of preFilteredItems) {
