    d.emoji = settingByOrderDay.emoji;
    d.order_number_stamped = `${settingByOrderDay.emoji} ${d.order_number || ''}`;

    output.push({ json: d });
}

return output;

const timeline = $input.first().json.chat_timeline || [];
// 1. หาข้อความลูกค้าที่มี / และมี ม. ต.
let customerAddrRaw = [...timeline].reverse().find(t => t.includes('[ลูกค้า:') && t.includes('/') && t.includes('ม.')) || "";

let parts = customerAddrRaw.split('/').map(s=>s.trim());
let name = parts[0]?.replace(/.*\[ลูกค้า:\s*/,'') || "";
let address = parts[1] || "";
let phone = (customerAddrRaw.match(/0[0-9\-]{8,10}/)?.[0] || "").replace(/-/g,'');

// 2. COD เอาจากสรุปของเพจ อันนี้จริง
let pageBlock = [...timeline].reverse().find(t=>t.includes('COD:')) || "";
let cod = pageBlock.match(/COD:\s*([0-9,]+)/)?.[1] || "350";
let product = pageBlock.match(/CAVALLO[^\n]+คอต\.?|MOND[^\n]+คอต\.?|VESS[^\n]+คอต\.?/i)?.[0] || "CAVALLO_WATERMELON 1 คอต";

return [{
  ...$input.first().json,
  customer_name: name, // นายมนตรี กาลพรมมา
  phone: phone, // 0806783457
  short_address: address, // อาคารที่พักนักท่องเที่ยวบึงบอระเพ็ด ม.3...
  cod_amount: Number(cod.replace(/,/g,'')),
  final_display_for_packer: product.trim(),
  single_cleaned_block: `${name}\n${phone}\n${address}\nCOD ${cod} - ${product}`
}];

// n8n Code node: 🌌 HERMES_CHAT_RAW_ALL
// Mode: Run Once for All Items
// Input: one item per page from 🌌 HERMES_FETCH_FACEBOOK_ALL.
// This node does not filter COD or speaker; it preserves every message and timestamp.

const output = [];
const now = new Date().toISOString();

function cleanText(value) {
  return String(value ?? "").replace(/udfe[0-9a-fA-F]{0,4}/gi, "").replace(/\\?ud[0-9a-fA-F]+/gi, "").replace(/\\n/g, "\n").replace(/\\\s*n/gi, "\n").trim();
}
function attachmentsOf(message) {
  if (Array.isArray(message.attachments?.data)) return message.attachments.data;
  return Array.isArray(message.attachments) ? message.attachments : [];
}
function imageUrlsOf(attachments) {
  const urls = [];
  for (const attachment of attachments) {
    const candidates = [
      attachment.url,
      attachment.file_url,
      attachment.payload?.url,
      attachment.image_data?.url,
      attachment.target?.url,
    ];
    for (const url of candidates) {
      if (typeof url === "string" && /^https?:\/\//i.test(url) && !urls.includes(url)) urls.push(url);
    }
  }
  return urls;
}

for (const item of $input.all()) {
  const source = item.json ?? {};
  const graph = source.facebook_response ?? source.body ?? source;
  const pageId = String(source.page_id ?? source.pageId ?? graph.page_id ?? "");
  const pageName = source.page_name ?? source.pageName ?? null;
  const conversations = Array.isArray(graph.data) ? graph.data : Array.isArray(graph.conversations) ? graph.conversations : [];

  for (const conversation of conversations) {
    const conversationId = String(conversation.id ?? "");
    const participants = Array.isArray(conversation.participants?.data) ? conversation.participants.data : [];
    // HTTP Request nodes can return only Facebook's body and drop the input
    // config. Recover the page context from the participant with a long Meta
    // Page ID; this matches the real Graph response shape.
    const inferredPage = participants.find(participant => String(participant.id ?? "").length > 10);
    const conversationPageId = pageId || String(inferredPage?.id ?? "");
    const conversationPageName = pageName || inferredPage?.name || null;
    const messages = Array.isArray(conversation.messages?.data) ? conversation.messages.data : [];

    if (!messages.length) {
      output.push({ json: { record_type: "conversation", page_id: conversationPageId, page_name: conversationPageName, page_index: source.page_index ?? null, conversation_id: conversationId, conversation_key: conversationId, conversation_updated_time: conversation.updated_time ?? null, conversation_message_count: conversation.message_count ?? 0, conversation_unread_count: conversation.unread_count ?? 0, can_reply: conversation.can_reply ?? null, participants, fetched_at: source.fetched_at ?? now, fetch_status: source.fetch_status ?? "success", raw_conversation: conversation } });
      continue;
    }

    for (const message of messages) {
      const messageId = String(message.id ?? "");
      const fromId = String(message.from?.id ?? "");
      const fromEmail = String(message.from?.email ?? "");
      const occurredAt = message.created_time ?? conversation.updated_time ?? source.fetched_at ?? now;
      const text = cleanText(message.message ?? message.text ?? "");
      const attachments = attachmentsOf(message);
      const imageUrls = imageUrlsOf(attachments);
      const isEcho = message.is_echo === true;
      // Some Meta exports mark page automation as is_echo=false and may also
      // return a different room/page ID. The explicit page email marker and
      // sender/page-name match are stronger evidence than the room ID alone.
      const explicitPageSender = /@facebook\.com$/i.test(fromEmail)
        || Boolean(conversationPageName && message.from?.name && message.from.name === conversationPageName);
      const speakerHint = isEcho || (conversationPageId && fromId === conversationPageId) || explicitPageSender ? "page" : "customer";
      const dedupeKey = ["meta", conversationPageId, conversationId, messageId || occurredAt, text.slice(0, 100)].join(":");

      output.push({ json: {
        record_type: "message",
        page_id: conversationPageId, page_name: conversationPageName, page_index: source.page_index ?? null,
        conversation_id: conversationId, conversation_key: conversationId,
        conversation_updated_time: conversation.updated_time ?? null,
        conversation_message_count: conversation.message_count ?? null,
        conversation_unread_count: conversation.unread_count ?? null,
        can_reply: conversation.can_reply ?? null, participants,
        message_id: messageId || null, source_message_id: messageId || null, dedupe_key: dedupeKey,
        message_text: text, message_type: imageUrls.length ? "image" : attachments.length ? "attachment" : "text", attachments,
        attachment_count: attachments.length, has_image: imageUrls.length > 0, image_urls: imageUrls,
        shares: message.shares ?? null, sticker: message.sticker ?? null,
        message_from: message.from ?? null, message_from_id: fromId || null, message_from_name: message.from?.name ?? null,
        message_from_is_page: explicitPageSender, message_is_echo: isEcho, speaker_hint: speakerHint,
        message_created_time: message.created_time ?? null, occurred_at: occurredAt,
        fetched_at: source.fetched_at ?? now, fetch_status: source.fetch_status ?? "success",
        raw_conversation: conversation, raw_message: message,
      } });
    }
  }
}

// n8n stops a branch when a Code node returns zero items. Return a harmless
// status item on an empty API window; downstream processors skip non-message
// records, so this prevents a false workflow stop without inventing a chat.
if (!output.length) {
  output.push({
    json: {
      record_type: "sync_status",
      status: "empty",
      message_count: 0,
      fetched_at: now,
      note: "Facebook API returned no conversations/messages in this window",
    },
  });
}

return output;

// Downstream processors decide the final speaker/table. Keep raw_message for audit and troubleshooting.

// n8n Code node: 💬 CUSTOMER_CHAT_PROCESSOR
// Mode: Run Once for All Items
// Input: 🌌 HERMES_CHAT_RAW_ALL
// Output: one item per customer message for chat_customer_messages.

const output = [];
const seen = new Set();

for (const item of $input.all()) {
  const row = item.json ?? {};

  // Support both HERMES versions:
  // - new: record_type="message"
  // - older raw node: message_id/message_text without record_type
  const isMessage = row.record_type === "message"
    || Boolean(row.message_id || row.source_message_id || row.message_text);
  if (!isMessage) continue;

  const pageId = String(row.page_id ?? row.pageId ?? "");
  const from = row.message_from ?? row.from ?? {};
  const fromId = String(row.message_from_id ?? row.sender_id ?? from.id ?? "");
  const fromName = String(row.message_from_name ?? row.sender_name ?? from.name ?? "");
  const fromEmail = String(from.email ?? row.message_from_email ?? "");
  const pageName = String(row.page_name ?? row.pageName ?? "");

  // Prefer explicit classification from HERMES. Keep old fallbacks so this
  // node remains compatible with the previous raw output shape.
  const isPage = row.speaker_hint === "page"
    || row.message_from_is_page === true
    || row.message_is_echo === true
    || row.is_echo === true
    || (fromId !== "" && pageId !== "" && fromId === pageId)
    || /@facebook\.com$/i.test(fromEmail)
    || (pageName !== "" && fromName !== "" && pageName === fromName);
  if (isPage) continue;

  const conversationKey = String(row.conversation_key ?? row.conversation_id ?? row.thread_id ?? row.threadId ?? "");
  const messageId = String(row.source_message_id ?? row.message_id ?? "");
  const text = row.message_text ?? row.message ?? row.text ?? "";
  const occurredAt = row.occurred_at ?? row.message_created_time ?? row.created_time ?? null;
  const dedupeKey = String(row.dedupe_key ?? `meta:${pageId}:${conversationKey}:${messageId || occurredAt || text}`);
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);

  output.push({ json: {
    source_message_id: messageId || null,
    dedupe_key: dedupeKey,
    page_id: pageId,
    page_name: pageName || null,
    conversation_key: conversationKey,
    customer_id: fromId || null,
    customer_name: fromName || null,
    speaker_type: "customer",
    side: "left",
    message_text: String(text),
    message_type: row.message_type ?? (Array.isArray(row.attachments) && row.attachments.length ? "attachment" : "text"),
    attachments_json: row.attachments_json ?? row.attachments ?? [],
    image_urls: row.image_urls ?? [],
    has_image: row.has_image === true || (Array.isArray(row.image_urls) && row.image_urls.length > 0),
    attachment_count: row.attachment_count ?? (Array.isArray(row.attachments) ? row.attachments.length : 0),
    shares_json: row.shares_json ?? row.shares ?? null,
    sticker_json: row.sticker_json ?? row.sticker ?? null,
    occurred_at: occurredAt,
    source_created_at: row.message_created_time ?? row.created_time ?? null,
    synced_at: row.fetched_at ?? new Date().toISOString(),
    raw_payload: row.raw_payload ?? {
      page_id: pageId,
      conversation_id: row.conversation_id ?? conversationKey,
      message_id: row.message_id ?? messageId,
      message: text,
      from,
      is_echo: row.message_is_echo ?? row.is_echo ?? false,
      attachments: row.attachments ?? [],
      shares: row.shares ?? null,
      sticker: row.sticker ?? null,
    },
  } });
}

// Return a status item instead of zero items so n8n does not stop when a
// polling window contains only page messages.
if (!output.length) {
  return [{ json: { record_type: "sync_status", status: "no_customer_messages", message_count: 0, synced_at: new Date().toISOString() } }];
}
return output;

// Supabase destination: chat_customer_messages; Upsert conflict: dedupe_key.

// n8n Code node: 🟣 PAGE_CHAT_PROCESSOR
// Mode: Run Once for All Items
// Input: 🌌 HERMES_CHAT_RAW_ALL. Output maps to chat_page_messages.

const output = [];
const seen = new Set();
for (const item of $input.all()) {
  const row = item.json;
  if (row.record_type !== "message") continue;
  const pageId = String(row.page_id ?? "");
  const fromId = String(row.message_from_id ?? "");
  const isPage = row.speaker_hint === "page" || row.message_from_is_page === true || row.message_is_echo === true || fromId === pageId;
  if (!isPage) continue;
  const dedupeKey = String(row.dedupe_key ?? `meta:${pageId}:${row.conversation_key}:${row.source_message_id ?? ""}`);
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  output.push({ json: {
    source_message_id: row.source_message_id ?? null,
    dedupe_key: dedupeKey,
    page_id: pageId, page_name: row.page_name ?? null,
    conversation_key: row.conversation_key ?? row.conversation_id ?? null,
    page_sender_id: fromId || null, page_sender_name: row.message_from_name ?? null,
    speaker_type: "page", side: "right",
    message_text: row.message_text ?? "", message_type: row.message_type ?? "text",
    attachments_json: row.attachments ?? [], image_urls: row.image_urls ?? [], has_image: row.has_image === true, attachment_count: row.attachment_count ?? 0, shares_json: row.shares ?? null, sticker_json: row.sticker ?? null,
    occurred_at: row.occurred_at ?? row.message_created_time ?? null,
    source_created_at: row.message_created_time ?? null, synced_at: row.fetched_at ?? new Date().toISOString(),
    raw_payload: { page_id: row.page_id, conversation_id: row.conversation_id, message_id: row.message_id, message: row.message_text, from: row.message_from, is_echo: row.message_is_echo, attachments: row.attachments, shares: row.shares, sticker: row.sticker },
  } });
}
return output;

// Supabase destination: chat_page_messages; operation Upsert; conflict column: dedupe_key.
